plugins {
    id("com.gradleup.shadow") version "8.3.5"
}

// hibernate-core as the Forge-like platforms can load it, nested in their jars:
//
//  * ANTLR relocated inside it. Hibernate's query parser needs ANTLR 4.13; NeoForge
//    1.21.1 ships 4.13.1 but Forge 1.20.1 ships 4.9.1, whose runtime cannot read
//    grammars generated by 4.10+, and neither loader allows a second module of the same
//    name. A private copy under CoffeeLib's package works on both.
//  * FMLModType: GAMELIBRARY, so the loader puts it in the game layer, next to the mods.
//    Hibernate generates subclasses of a mod's entities (lazy proxies) in the entity's
//    own package, which needs its module to read the mod's; from a lower layer it
//    cannot ("module org.hibernate.orm.core does not read module <mod>").
//
// Everything else of Hibernate's is nested as it is published (see
// gradle/nested-libraries.gradle). Nothing here is part of any public API: mods compile
// against the real org.hibernate.orm:hibernate-core.
val hibernateVersion = project.property("hibernate_version").toString()

val repacked: Configuration by configurations.creating {
    isTransitive = false
}

dependencies {
    repacked("org.hibernate.orm:hibernate-core:$hibernateVersion")
    repacked("org.antlr:antlr4-runtime:4.13.0")
}

tasks.shadowJar {
    archiveBaseName.set("hibernate-core")
    archiveVersion.set(hibernateVersion)
    archiveClassifier.set("coffeelib")
    configurations = listOf(repacked)
    relocate("org.antlr", "net.loyalnetwork.coffeelib.libs.antlr")
    mergeServiceFiles()
    exclude("META-INF/*.SF", "META-INF/*.DSA", "META-INF/*.RSA", "META-INF/maven/**", "module-info.class",
        "META-INF/versions/**")
    manifest {
        attributes(
            "Automatic-Module-Name" to "org.hibernate.orm.core",
            "FMLModType" to "GAMELIBRARY",
        )
    }
}

tasks.jar {
    enabled = false
}
tasks.assemble {
    dependsOn(tasks.shadowJar)
}
